PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "role" varchar not null default 'student', "phone" varchar, "date_of_birth" date, "level" varchar, "bio" text, "profile_photo" varchar, "valid" tinyint(1) not null default '0', "preferences" text, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "subjects" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "level" varchar, "sub_system" varchar default 'francophone', "color" varchar not null default '3B82F6', "icon" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "courses" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "description" text not null, "objectives" text, "prerequisites" text, "price" numeric not null default '0', "image" varchar, "difficulty" varchar not null default 'beginner', "estimated_duration" integer, "is_published" tinyint(1) not null default '0', "user_id" integer not null, "subject_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("subject_id") references "subjects"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "lessons" ("id" integer primary key autoincrement not null, "title" varchar not null, "content" text not null, "video_url" varchar, "duration" integer not null, "order" integer not null default '0', "is_free" tinyint(1) not null default '0', "course_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "enrollments" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer not null, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "progress" ("id" integer primary key autoincrement not null, "user_id" integer not null, "lesson_id" integer not null, "is_completed" tinyint(1) not null default '0', "time_spent" integer not null default '0', "last_accessed" datetime, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("lesson_id") references "lessons"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "quizzes" ("id" integer primary key autoincrement not null, "title" varchar not null, "description" text not null, "time_limit" integer, "max_attempts" integer not null default '1', "lesson_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("lesson_id") references "lessons"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "questions" ("id" integer primary key autoincrement not null, "question" text not null, "type" varchar not null default 'true_false', "options" text, "correct_answer" varchar not null, "points" integer not null default '1', "explanation" text, "order" integer, "quiz_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("quiz_id") references "quizzes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "quiz_attempts" ("id" integer primary key autoincrement not null, "user_id" integer not null, "quiz_id" integer not null, "score" integer not null, "time_spent" integer not null default '0', "completed_at" datetime, "answers" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("quiz_id") references "quizzes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "subscriptions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "type" varchar not null, "stripe_id" varchar not null, "stripe_price" varchar, "quantity" integer not null default '1', "trial_ends_at" datetime, "ends_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "payments" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer, "payment_id" varchar not null, "amount" numeric not null, "currency" varchar not null default 'eur', "status" varchar not null, "payment_method" varchar not null, "metadata" text, "paid_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE IF NOT EXISTS "notification_preferences" ("id" integer primary key autoincrement not null, "user_id" integer not null, "notification_type" varchar not null, "channels" text, "is_enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "notification_templates" ("id" integer primary key autoincrement not null, "type" varchar not null, "subject" varchar not null, "body" text not null, "channel" varchar not null, "is_active" tinyint(1) not null default '1', "variables" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "learning_streaks" ("user_id" integer not null, "current_streak" integer not null default '0', "longest_streak" integer not null default '0', "last_study_date" datetime, "total_study_days" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "study_sessions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer, "lesson_id" integer, "duration_minutes" integer not null, "date" date not null, "started_at" datetime, "ended_at" datetime, "topics_covered" text, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete set null, foreign key("lesson_id") references "lessons"("id") on delete set null);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "courses_user_id_is_published_index" on "courses" ("user_id", "is_published");
CREATE UNIQUE INDEX "courses_slug_unique" on "courses" ("slug");
CREATE UNIQUE INDEX "lessons_course_id_order_unique" on "lessons" ("course_id", "order");
CREATE UNIQUE INDEX "enrollments_user_id_course_id_unique" on "enrollments" ("user_id", "course_id");
CREATE INDEX "enrollments_course_id_enrolled_at_index" on "enrollments" ("course_id", "enrolled_at");
CREATE UNIQUE INDEX "progress_user_id_lesson_id_unique" on "progress" ("user_id", "lesson_id");
CREATE UNIQUE INDEX "subscriptions_stripe_id_unique" on "subscriptions" ("stripe_id");
CREATE UNIQUE INDEX "payments_payment_id_unique" on "payments" ("payment_id");
CREATE INDEX "notifications_notifiable_type_notifiable_id_index" on "notifications" ("notifiable_type", "notifiable_id");
CREATE UNIQUE INDEX "notification_preferences_user_id_notification_type_unique" on "notification_preferences" ("user_id", "notification_type");
CREATE UNIQUE INDEX "learning_streaks_user_id_unique" on "learning_streaks" ("user_id");
CREATE INDEX "study_sessions_user_id_date_index" on "study_sessions" ("user_id", "date");
CREATE INDEX "study_sessions_date_index" on "study_sessions" ("date");
COMMIT;
